import type {CEFRLevel,GrammarLesson,GrammarExercise,ExerciseKind} from '../types/grammar.ts';

// Original teaching text. Level tags are editorial pathways, not universal CEFR rules.
const references=[{title:'British Council · grammar syllabus',url:'https://learnenglish.britishcouncil.org/free-resources/grammar'}, {title:'Council of Europe · CEFR descriptors',url:'https://www.coe.int/en/web/common-european-framework-reference-languages/cefr-descriptors'}];
type Task={prompt:string;answers:string[];explanation:string;kind?:ExerciseKind;choices?:string[];vocabulary?:{word:string;meaning:string}};
interface Unit {id:string;title:string;level:CEFRLevel;category:string;concept:string;context:string;structure:string;examples:[string,string][];contrast:string;difference:string;wrong:string;right:string;why:string;tasks:Task[];production:string;model:string}
const units:Unit[]=[
 {id:'sentence-foundations',title:'Clauses, pronouns and basic word order',level:'A1',category:'Foundations',concept:'A finite statement normally needs a subject and a verb. A subject pronoun replaces a person or thing already identified; an object pronoun follows a verb or preposition. English relies on word order to distinguish who acts from who receives the action.',context:'Use a subject–verb–object frame to describe a simple action. Be can link a subject to a description without an object. Commands are a useful exception: their subject you is usually understood.',structure:'Subject + finite verb + object/complement; subject I/she/they → object me/her/them',examples:[['She helps him.','She performs the action; him receives it.'],['They are ready.','Ready describes the subject; it is not an object.']],contrast:'She helps him / He helps her',difference:'Changing pronouns and their positions changes the roles. An English statement is not normally formed by reversing the subject and verb.',wrong:'Her helps I.',right:'She helps me.',why:'The actor needs a subject form and the receiver an object form.',tasks:[{prompt:'Choose a subject pronoun: ___ are ready.',answers:['They'],choices:['Them','They','Their'],explanation:'They is a subject form. Them is an object and their marks possession.'},{prompt:'Replace Esra with a pronoun: I know Esra. Write the whole sentence.',answers:['I know her.'],kind:'transformation',explanation:'Her is the object of know; she would be a subject form.'}],production:'Write one statement with a subject pronoun and an object pronoun.',model:'She knows me.'},
 {id:'prepositions-time',title:'Time, place and countability',level:'A2',category:'Foundations',concept:'Prepositions relate an event or object to a time or place. At often identifies a point, on a day or surface, and in an enclosed place or longer period. These are patterns with conventional exceptions, not literal laws.',context:'Countability also controls quantity phrases: many goes with plural count nouns; much goes with uncountable nouns. A piece of advice makes an uncountable idea countable through a unit.',structure:'at six / on Monday / in October; many books / much information',examples:[['The meeting starts at six on Monday.','At gives the clock time; on identifies the day.'],['There is some useful information in the report.','Information is uncountable; in identifies its location.']],contrast:'Much information / many reports',difference:'The same real-world material can be packaged as an uncountable substance or as countable documents. Choose grammar for the noun actually used.',wrong:'She gave me many useful advices.',right:'She gave me much useful advice.',why:'Advice is uncountable in standard English. Some useful advice is a more usual affirmative phrasing.',tasks:[{prompt:'The interview is ___ Tuesday. Choose the preposition.',answers:['on'],choices:['at','in','on'],explanation:'A named day takes on, not at or in.'},{prompt:'Rewrite using two pieces of: She gave me two advices.',answers:['She gave me two pieces of advice.'],kind:'error-correction',explanation:'Pieces provides a plural countable unit; advice remains uncountable.'}],production:'Describe a future meeting with its day and clock time.',model:'We are meeting on Thursday at seven.'},
 {id:'perfect-aspect',title:'Present and past perfect: result versus duration',level:'B2',category:'Tenses & aspect',concept:'Perfect simple foregrounds a result, quantity or completed experience. Perfect continuous foregrounds the activity and its duration or visible effects. Neither form alone guarantees that an activity has ended.',context:'Choose the reference point first: have/has looks back from now; had looks back from a past moment. State verbs usually remain simple. A completed numerical result normally favours the simple perfect.',structure:'have/has/had + participle; have/has/had + been + -ing',examples:[['She has revised three chapters.','The measurable result matters.'],['She had been revising for hours when the alarm rang.','Duration is viewed from a later past event.'],['Environmental conditions have been deteriorating steadily over the past decade.','An ongoing process links a past period to now.']],contrast:'I have read the report / I have been reading the report',difference:'The first normally presents the report as completed. The second foregrounds the process and does not assert completion. Compare had read/had been reading from a past reference point.',wrong:'I have been knowing her for years.',right:'I have known her for years.',why:'Know normally expresses a state and takes the simple perfect.',tasks:[{prompt:'Use present perfect continuous of deteriorate: Environmental conditions ___ steadily over the past decade.',answers:['have been deteriorating'],vocabulary:{word:'deteriorate',meaning:'to become worse'},explanation:'Plural conditions requires have; been deteriorating foregrounds the continuing process.'},{prompt:'Use past perfect continuous: She started waiting at two. At four, she was still waiting. Begin: By four, she…',answers:['By four, she had been waiting for two hours.'],kind:'transformation',explanation:'Had been waiting looks back from four and preserves the two-hour duration.'},{prompt:'Choose the form expressing a completed quantity: She ___ three reports so far.',answers:['has written'],choices:['has written','has been writing','had writing'],explanation:'Has written presents three completed reports; the continuous foregrounds activity instead.'}],production:'Contrast a completed study result with an ongoing study activity, using both perfect aspects.',model:'I have read two chapters, but I have been studying the third all afternoon.'},
 {id:'future-perfect',title:'Future perfect and future perfect continuous',level:'B2',category:'Tenses & aspect',concept:'Future perfect looks back from a future deadline. The simple form foregrounds completion; the continuous foregrounds accumulated duration up to that point.',context:'A by-phrase supplies the future reference point. In a time clause after by the time, use an appropriate present form rather than automatically adding will.',structure:'will have + participle; will have been + -ing; by the time + present',examples:[['By Friday, we will have completed the survey.','Completion precedes the future deadline.'],['By June, she will have been working here for ten years.','Duration accumulates up to a future point.']],contrast:'Will be working / will have been working',difference:'Future continuous places you inside an activity at a future moment. Future perfect continuous looks backwards over its duration from that moment.',wrong:'By the time you will arrive, I will have left.',right:'By the time you arrive, I will have left.',why:'This future time clause uses present simple arrive.',tasks:[{prompt:'Use future perfect of complete: By Friday, we ___ the survey.',answers:['will have completed'],explanation:'Will have completed presents a result before the deadline.'},{prompt:'Rewrite with future perfect continuous: In June, her work here will reach ten years. Begin: By June, she…',answers:['By June, she will have been working here for ten years.'],kind:'transformation',explanation:'Will have been working expresses the accumulated duration without implying that she leaves.'},{prompt:'By the time he ___, we will have finished.',choices:['arrives','will arrive','arriving'],answers:['arrives'],explanation:'A future time clause normally uses the present simple.'}],production:'Describe something you expect to have completed by a real deadline.',model:'By December, I will have completed the course.'},
 {id:'narrative-aspect',title:'Narrative tenses, temporary states and tense consistency',level:'B2',category:'Tenses & aspect',concept:'A narrative uses past simple for its event line, past continuous for unfolding background and past perfect for earlier events. Continuous forms select a temporary or developing viewpoint, not simply a long action.',context:'Some state verbs acquire an action meaning: I think means hold an opinion; I am thinking means actively considering. Always with the continuous can convey irritation. Keep a stable narrative reference point unless the time genuinely shifts.',structure:'past event → earlier had + participle; temporary behaviour: be + being + adjective',examples:[['The road was flooding because it had been raining all night.','An ongoing scene has an earlier continuing cause.'],['He is being unusually cautious today.','Being describes temporary behaviour, not his permanent personality.']],contrast:'He is rude / He is being rude',difference:'The first describes a characteristic; the second evaluates current behaviour. Not all adjectives allow this behavioural reading.',wrong:'When I reached the office, I discover that I had lost my keys.',right:'When I reached the office, I discovered that I had lost my keys.',why:'Discover belongs to the same past event line; the loss is earlier.',tasks:[{prompt:'Keep the past narrative: When I arrived, I ___ that the door was locked. Use discover.',answers:['discovered'],explanation:'Past simple maintains the event line; present discover would shift time without a reason.'},{prompt:'Rewrite the earlier loss with past perfect: I lost the key before I reached the office. Begin: When I reached the office, I…',answers:['When I reached the office, I had lost the key.'],kind:'transformation',explanation:'Had lost marks the loss as earlier than the arrival; the key remains lost at that reference point.'},{prompt:'Which describes temporary behaviour?',choices:['He is being impatient today.','He knows the route.','He owns a car.'],answers:['He is being impatient today.'],explanation:'Is being + a behavioural adjective selects a temporary interpretation.'}],production:'Write a two-sentence narrative with background, a main event and an earlier cause.',model:'I was walking home when the lights failed. A storm had damaged the power lines.'},
 {id:'mixed-inverted-conditionals',title:'Mixed, inverted and implied conditionals',level:'C1',category:'Conditionals',concept:'Mixed conditionals connect different times: an unreal past cause can have an unreal present consequence. Inversion with had, were or should replaces if in a more formal conditional clause, without changing the hypothetical relationship.',context:'An implied condition may be expressed by without, otherwise or but for. Identify its time and meaning rather than forcing every condition into one numbered pattern. Zero conditionals describe general relationships rather than a particular prediction.',structure:'If + had + participle, would + base (past → now); Had + subject + participle; Were + subject + to-infinitive; Should + subject + base',examples:[['Had I accepted the offer, I would be living abroad now.','An unreal past decision has a present consequence.'],['Without your help, we would have failed.','The missing condition is if you had not helped.']],contrast:'If I had studied, I would have passed / I would be qualified now',difference:'Would have passed locates the imagined result in the past. Would be qualified locates the resulting state now. Inversion does not change those times.',wrong:'Had I would known, I would have helped.',right:'Had I known, I would have helped.',why:'Had is already the inverted perfect auxiliary; would does not belong in this condition.',tasks:[{prompt:'Invert without changing meaning: If I had known, I would have helped. Begin Had.',answers:['Had I known, I would have helped.'],kind:'transformation',explanation:'Move had before I and remove if; preserve the unreal past result.'},{prompt:'Past cause, present result: If I had accepted the job, I ___ abroad now. Use live with would and continuous aspect.',answers:['would be living'],explanation:'Would be living describes the present hypothetical result, not a completed past consequence.'},{prompt:'Which sentence expresses a general relationship?',choices:['If ice warms sufficiently, it melts.','Had I known, I would have called.','If I had stayed, I would be tired now.'],answers:['If ice warms sufficiently, it melts.'],explanation:'Present + present expresses a zero conditional; the other choices are counterfactual.'}],production:'Write an unreal past condition with a present result, then invert its condition.',model:'Had I learned to drive earlier, I would be more independent now.'},
 {id:'conditional-alternatives',title:'Unless, provided that, supposing and as long as',level:'B2',category:'Conditionals',concept:'Conditional conjunctions express different assumptions. Unless means except if; provided that and as long as introduce requirements. Supposing invites an imagined scenario rather than imposing a contractual condition.',context:'Use unless only when an except-if reading preserves the meaning. Do not automatically convert every if-not clause: regret about a known past fact often needs a counterfactual if-clause instead.',structure:'unless + affirmative clause; provided (that) / as long as + condition; supposing + hypothetical clause',examples:[['We can proceed provided that everyone agrees.','Agreement is a prerequisite.'],['Unless the deadline changes, we will submit on Friday.','Friday remains the plan except in the case of a changed deadline.']],contrast:'Unless / even if',difference:'Unless introduces an exception to the result. Even if says the result survives the stated condition, so replacing one with the other reverses the logic.',wrong:'Unless you do not save it, you will lose your work.',right:'Unless you save it, you will lose your work.',why:'For the intended warning, unless already contains the negative condition.',tasks:[{prompt:'Rewrite with Unless: If you do not save it, you will lose your work.',answers:['Unless you save it, you will lose your work.'],kind:'transformation',explanation:'Unless you save it means if you do not save it; do not add another negative.'},{prompt:'Choose a requirement marker: You may borrow it ___ you return it tomorrow.',choices:['provided that','even though','despite'],answers:['provided that'],explanation:'Provided that introduces the condition for borrowing; even though is concession and despite needs a nominal complement.'}],production:'State a permission with a condition, then paraphrase its negative exception.',model:'You may enter as long as you have a ticket. Unless you have a ticket, you may not enter.'},
 {id:'unreal-past',title:'Wish, if only, would rather and it is time',level:'B2',category:'Conditionals',concept:'Past morphology can mark distance from reality rather than past time. Wish + past describes an unreal present; wish + past perfect expresses past regret. Would rather + a different subject uses past simple for a present or future preference.',context:'Wish + would often requests a change in behaviour outside the speaker’s control. It is time + past implies that an action is due, possibly overdue. These constructions express attitudes rather than ordinary past facts.',structure:'wish + past / past perfect; would rather + subject + past; it is time + subject + past',examples:[['I wish I knew the answer.','The unreal state concerns now.'],['I would rather you stayed tonight.','The other person’s future action is expressed with a past form.']],contrast:'Had better / would rather',difference:'Had better + bare infinitive gives advice with a possible consequence. Would rather + bare infinitive expresses the same subject’s preference; a different subject needs a finite past clause.',wrong:'I would rather you to stay.',right:'I would rather you stayed.',why:'A different subject after would rather needs a finite clause, not an object plus infinitive.',tasks:[{prompt:'Past regret: I wish I ___ (check) the figures before publishing.',answers:['had checked'],explanation:'Past perfect locates the unreal alternative before the completed publication.'},{prompt:'Rewrite with would rather: I prefer you to stay tonight. Begin I would rather.',answers:['I would rather you stayed tonight.'],kind:'transformation',explanation:'You is a different subject; stayed expresses a present/future preference, not past time.'},{prompt:'It is time we ___ home. Use go.',answers:['went'],explanation:'It is time + subject + past simple expresses that an action is due.'}],production:'Express one present wish and one regret about an earlier decision.',model:'I wish I spoke more confidently. I wish I had practised before the interview.'},
 {id:'modal-deduction',title:'Deduction, past modals and degrees of necessity',level:'B2',category:'Modals & deduction',concept:'Must can present a strong inference, cannot a strong negative inference, and may/might/could a possibility. These are judgments from evidence, not guarantees. Add have + participle to locate an inference in the past.',context:'Should have often expresses an unfulfilled expectation or criticism; could have may express a missed opportunity or a past possibility. Must have is not the usual past obligation form: had to expresses that obligation.',structure:'must/might/cannot + base; modal + have + participle; had to = past obligation',examples:[['The floor is wet; someone must have cleaned it.','Evidence supports an inference about an earlier action.'],['You should have checked the source.','This evaluates an action that was expected but not performed.']],contrast:'Must have / should have',difference:'Must have draws a conclusion from evidence. Should have evaluates an expected or advisable action. Could have and might have can express uncertainty, so context matters.',wrong:'She must had forgotten.',right:'She must have forgotten.',why:'A core modal takes the bare form have, followed by a participle.',tasks:[{prompt:'Strong past deduction: She ___ have left; her coat is gone.',choices:['must','should to','must to'],answers:['must'],explanation:'Must have left marks a strong inference; a core modal takes bare have.'},{prompt:'Rewrite as criticism using should have: You did not check the source, but it was advisable. Begin You.',answers:['You should have checked the source.'],kind:'transformation',explanation:'Should have checked expresses the unperformed advisable action without claiming it occurred.'},{prompt:'Past external obligation: Yesterday I ___ attend the hearing.',answers:['had to'],explanation:'Had to describes past necessity; must have attended would normally be a deduction.'}],production:'Make two different evidence-based guesses about a past event, with different certainty.',model:'She must have seen the email, but she might have misunderstood the deadline.'},
 {id:'clefts-fronting',title:'Clefts, pseudo-clefts, fronting and information focus',level:'C1',category:'Sentence structures',concept:'A cleft splits a message so that one part receives contrastive focus. An it-cleft highlights a constituent; a pseudo-cleft begins with a what-clause. Fronting moves a constituent to the beginning to connect it with the discourse.',context:'Use these structures to correct an assumption or organize old and new information. Fronting an object does not automatically trigger subject–auxiliary inversion; negative or restrictive adverbials can.',structure:'It + be + focus + that/who + clause; What + clause + be + focus; object + subject + verb',examples:[['It was the deadline that worried me, not the workload.','The deadline corrects a competing explanation.'],['What we need is reliable evidence.','The what-clause sets up the topic; evidence is the focus.'],['That proposal I can support.','The object is fronted, but statement order remains.']],contrast:'Fronting / inversion',difference:'That proposal I support fronts an object without an auxiliary. Only then did I understand fronts a restrictive time phrase and requires inversion.',wrong:'It was Esra which solved the problem.',right:'It was Esra who solved the problem.',why:'Who is appropriate for the focused person; that is also possible in this it-cleft.',tasks:[{prompt:'Focus the subject with an it-cleft: The deadline worried me. Begin It was the deadline.',answers:['It was the deadline that worried me.'],kind:'transformation',explanation:'The cleft focuses the original subject deadline while retaining the experiencer me.'},{prompt:'Complete the pseudo-cleft: What we need ___ reliable evidence.',answers:['is'],explanation:'The what-clause is treated as a singular subject here; evidence is the focused complement.'},{prompt:'Which object-fronted sentence preserves statement order?',choices:['That proposal I support.','That proposal do I support.','That proposal support I.'],answers:['That proposal I support.'],explanation:'Object fronting alone does not require inversion.'}],production:'Correct the assumption that workload worried you, using a cleft about the deadline.',model:'It was the deadline that worried me, not the workload.'},
 {id:'ellipsis-parallelism',title:'Ellipsis, substitution and parallel structure',level:'C1',category:'Sentence structures',concept:'Ellipsis omits recoverable material; substitution replaces it with forms such as do so, one or so. A reader must be able to reconstruct the intended meaning. Parallel structures give coordinated items comparable grammatical shapes.',context:'Use ellipsis for cohesion rather than repeating whole clauses. Do so normally substitutes for an action, not every state. Parallelism matters in both lists and paired constructions such as not only … but also.',structure:'I can attend, and she can too; action → do so; not only + X but also + parallel Y',examples:[['I expected her to object, but she did not.','Object is recoverable after did not.'],['The plan aims to reduce costs and improve access.','Two base-form complements are coordinated under to.']],contrast:'Do so / do it',difference:'Do so refers back to an activity in a more formal style. Do it can refer to a specific task and is common in speech. Neither should replace a whole clause when the reference is unclear.',wrong:'The plan aims to reduce costs and improving access.',right:'The plan aims to reduce costs and improve access.',why:'The coordinated complements share the infinitive frame.',tasks:[{prompt:'Fix only the nonparallel verb: The plan aims to reduce costs and improving access. Write the full sentence.',answers:['The plan aims to reduce costs and improve access.'],kind:'error-correction',explanation:'Reduce and improve share to. Improving breaks the parallel structure.'},{prompt:'Choose recoverable ellipsis: I can attend, and she ___ too.',choices:['can','does so','one'],answers:['can'],explanation:'Can leaves attend understood; does so would not preserve the modal meaning.'}],production:'Write two linked clauses, omitting a repeated verb phrase in the second.',model:'I have submitted the report, but she has not.'},
 {id:'reduced-participle',title:'Advanced relatives, reduced clauses and participles',level:'C1',category:'Sentence structures',concept:'Defining relative clauses can sometimes be reduced to participle modifiers. An -ing form normally has an active relationship with its noun; a past participle often has a passive one. A supplementary participle clause normally shares its understood subject with the main clause.',context:'Perfect participles mark an earlier event; a passive perfect participle can mark an earlier received action. Check time, voice and subject before reducing a clause. Not every finite relative can be reduced without changing meaning.',structure:'people who work → people working; documents that were signed → documents signed; having + participle; having been + participle',examples:[['The documents signed yesterday are confidential.','The documents received the action; signed is passive in meaning.'],['Having checked the data, Esra submitted the report.','Esra performs both actions, with checking first.']],contrast:'Reduced relative / supplementary participle clause',difference:'A reduced relative modifies a noun. Having checked the data supplies a circumstance for the main event and takes its understood subject from the main clause.',wrong:'Having checked the data, the report was submitted by Esra.',right:'Having checked the data, Esra submitted the report.',why:'The original grammar suggests that the report checked the data; the revised main subject is the checker.',tasks:[{prompt:'Reduce the passive relative: The documents that were signed yesterday are confidential.',answers:['The documents signed yesterday are confidential.'],kind:'transformation',explanation:'Signed retains passive meaning and yesterday retains the event time.'},{prompt:'Express the earlier action: ___ checked the data, Esra submitted the report.',answers:['Having'],explanation:'Having + participle marks the completed earlier action by Esra.'},{prompt:'Choose the clause without a dangling participle.',choices:['Walking home, Esra saw a fox.','Walking home, a fox was seen by Esra.','Walking home, the road was icy.'],answers:['Walking home, Esra saw a fox.'],explanation:'Esra is the walker and the main-clause subject; the other subjects do not supply the intended walker.'}],production:'Combine two actions by the same person using a perfect participle clause.',model:'Having reviewed the evidence, the committee revised its conclusion.'},
 {id:'nominal-clauses',title:'Nominal clauses and embedded questions',level:'B2',category:'Sentence structures',concept:'A clause can occupy a noun-like role as subject, object or complement. That-clauses report propositions; whether introduces alternatives; wh-clauses supply missing information. Embedded questions use statement order.',context:'Use embedded questions for indirect requests and nominal clauses to discuss ideas. Whether is safer than if before a to-infinitive or after a preposition. A nominal what-clause supplies its own referent; a relative which normally modifies an existing noun.',structure:'I wonder + wh-word + subject + verb; whether + to-infinitive; What + clause + finite verb',examples:[['I wonder why the results changed.','Why introduces an embedded question without did.'],['Whether to proceed remains uncertain.','The whether-clause functions as a subject.']],contrast:'What / that in nominal clauses',difference:'What she said means the thing she said. That she resigned expresses the proposition of her resignation; that does not stand for a missing object.',wrong:'I wonder why did the results change.',right:'I wonder why the results changed.',why:'Indirect questions use statement order; past tense returns to changed.',tasks:[{prompt:'Embed the question: Why did the results change? Begin I wonder.',answers:['I wonder why the results changed.'],kind:'transformation',explanation:'Remove question inversion and put past tense on changed.'},{prompt:'___ she said surprised me. Choose the meaning the thing that.',answers:['What'],choices:['What','That','Which'],explanation:'What supplies the missing object of said and means the thing that.'}],production:'Write an indirect question about the reason for a change.',model:'Could you explain why the schedule changed?'},
 {id:'perfect-complements',title:'Perfect infinitives, gerunds and verb complementation',level:'C1',category:'Verb patterns',concept:'A perfect nonfinite complement places its event before the time of the main verb. A to-infinitive uses to have + participle; a perfect gerund uses having + participle. The governing verb or preposition still determines the complement pattern.',context:'Compare seem to work with seem to have worked: the latter signals anterior time. Admit can take an -ing clause; deny cannot normally take a to-infinitive. Some simple gerunds already imply an earlier event, so perfect marking can be optional.',structure:'seem/claim + to have + participle; admit/deny + having + participle; preposition + -ing',examples:[['She seems to have misunderstood the instructions.','The misunderstanding precedes the present impression.'],['He admitted having copied the file.','Copying occurred before the admission.']],contrast:'Remember doing / remember to do',difference:'Remember doing recalls a past experience. Remember to do means not forgetting a required action. Choosing a perfect form does not override the verb’s complement pattern.',wrong:'He denied to have copied the file.',right:'He denied having copied the file.',why:'Deny selects an -ing complement, not a to-infinitive.',tasks:[{prompt:'Use a perfect infinitive of misunderstand: She seems ___ the instructions.',answers:['to have misunderstood'],explanation:'To have misunderstood makes the event earlier than the present impression.'},{prompt:'Correct only the complement: He denied to have copied the file.',answers:['He denied having copied the file.'],kind:'error-correction',explanation:'Deny requires an -ing complement; having copied preserves the explicit anterior reading.'}],production:'Report an apparently earlier event using seem and a perfect infinitive.',model:'The team seems to have resolved the discrepancy.'},
 {id:'reporting-causatives',title:'Reporting verbs and causative structures',level:'B2',category:'Verb patterns',concept:'Reporting verbs encode the speaker’s stance and select different complements. Advise takes an object plus to-infinitive; suggest can take an -ing or that-clause. Causative have/get + object + participle presents an arranged service or, in some contexts, an unwanted experience.',context:'Use a reporting verb only if it matches the original speech act. Causative have does not mean the subject personally performed the service. Have someone do and get someone to do have different complement patterns.',structure:'advise + object + to-infinitive; suggest + -ing / that-clause; have/get + object + participle',examples:[['She advised me to check the figures.','The advice is directed at me.'],['I had the monitor repaired.','I arranged the repair; another person performed it.']],contrast:'Have someone do / have something done',difference:'The first names the agent and uses a bare infinitive. The second makes the affected object prominent and uses a participle.',wrong:'She suggested me to leave.',right:'She suggested that I leave.',why:'Suggest does not normally select object + to-infinitive. That I should leave is also possible.',tasks:[{prompt:'Use causative have in the past: A technician repaired my monitor at my request. Begin I had.',answers:['I had my monitor repaired.'],kind:'transformation',explanation:'Had + object + participle describes an arranged service, not a repair done personally.'},{prompt:'She advised me ___ the figures. Use check.',answers:['to check'],explanation:'Advise + object selects a to-infinitive.'},{prompt:'Choose the grammatical report.',choices:['She suggested checking the figures.','She suggested me to check the figures.','She suggested to checking the figures.'],answers:['She suggested checking the figures.'],explanation:'Suggest allows an -ing complement; neither other complement is licensed.'}],production:'Describe a service you arranged without claiming to have performed it.',model:'I had my laptop repaired last week.'},
 {id:'advanced-passive',title:'Passive reporting and complex passive constructions',level:'C1',category:'Verb patterns',concept:'Reporting passives distance a claim from its source: it is believed that … or the subject is believed to …. The infinitive’s aspect locates the reported event relative to the reporting time. Modal passives combine modality with a received action.',context:'Use a passive reporting frame to attribute a claim, not to disguise an unsupported certainty. A perfect passive infinitive can encode an earlier received action: is believed to have been damaged.',structure:'It is believed that + clause; subject + is believed + to (have) + verb; modal + be + participle',examples:[['The archive is believed to have been damaged.','The reported damage precedes the present belief and is passive.'],['The environmental impact could be mitigated through stricter regulations.','A possible reduction is described from the affected object’s perspective.']],contrast:'Is said to be / is said to have been',difference:'To be normally overlaps with the reporting time; to have been explicitly locates a state or event earlier. Preserve this relation when transforming the clause.',wrong:'The archive is believed have been damaged.',right:'The archive is believed to have been damaged.',why:'The reporting passive requires a to-infinitive.',tasks:[{prompt:'Use a modal passive of mitigate: The environmental impact could ___ through stricter regulations.',answers:['be mitigated'],vocabulary:{word:'mitigate',meaning:'to make something less severe'},explanation:'Could takes bare be; mitigated is the passive participle.'},{prompt:'Rewrite with a personal reporting passive: People believe that the archive was damaged. Begin The archive.',answers:['The archive is believed to have been damaged.'],kind:'transformation',explanation:'Present belief remains is believed; the earlier passive event becomes to have been damaged.'},{prompt:'Current report, earlier active event: She is said ___ yesterday. Use leave.',answers:['to have left'],explanation:'The perfect infinitive preserves the earlier event; to leave would not express yesterday’s completed departure.'}],production:'Attribute an earlier event using a reporting passive without asserting it as verified fact.',model:'The manuscript is thought to have disappeared during the move.'},
 {id:'concession-contrast',title:'Concession, contrast and conditional concession',level:'B2',category:'Cohesion & academic English',concept:'Although introduces a finite concessive clause; despite takes a noun phrase or -ing clause. Whereas contrasts two propositions. Even though presents a fact; even if concedes a hypothetical condition.',context:'Concession acknowledges a fact that might lead to an opposite expectation. Contrast merely sets differences alongside each other. While can express time or contrast, so remove ambiguity in formal argument.',structure:'although + subject + finite verb; despite + noun/-ing; whereas + clause; even if + hypothetical clause',examples:[['Despite the limited sample, the pattern was consistent.','The limitation does not prevent the result.'],['Even if the grant is refused, the study will continue.','The result holds whether or not this hypothetical condition occurs.']],contrast:'Despite / although; even though / even if; whereas / while',difference:'Despite requires a nominal complement; although takes a clause. Even though treats the condition as factual, even if does not assert it. Whereas is unambiguously contrastive; while can also mean during.',wrong:'Despite the sample was small, the pattern was clear.',right:'Although the sample was small, the pattern was clear.',why:'A finite clause follows although. Despite the small sample would also be grammatical.',tasks:[{prompt:'Transform using Despite and a noun phrase: Although the sample was small, the pattern was clear.',answers:['Despite the small sample, the pattern was clear.'],kind:'transformation',explanation:'The small sample is a noun phrase; the concessive relationship and outcome remain.'},{prompt:'Choose the hypothetical concession: ___ the grant is refused, the study will continue.',choices:['Even if','Despite','Whereas of'],answers:['Even if'],explanation:'Even if introduces a possible obstacle without asserting its occurrence.'}],production:'Contrast two perspectives, then acknowledge a limitation without abandoning your claim.',model:'Whereas the first study measured speed, the second measured accuracy. Despite its small sample, the second provides useful evidence.'},
 {id:'cause-cohesion',title:'Cause, effect, discourse markers and cohesive reference',level:'B2',category:'Cohesion & academic English',concept:'Because introduces a reason clause; because of takes a nominal complement. Consequently links a result to an earlier proposition but does not grammatically join two independent clauses with only a comma.',context:'Cohesion also depends on clear reference: this finding is more precise than an isolated this when several ideas compete. Distinguish correlation from cause; a connective cannot make an unsupported causal claim valid.',structure:'because + clause; because of + noun; independent clause; consequently, independent clause',examples:[['The sensor failed because of excessive heat.','The reason is expressed as a noun phrase.'],['The sensor failed; consequently, the trial was postponed.','A semicolon separates two independent clauses.']],contrast:'Because / therefore; correlation / cause',difference:'Because subordinates a reason. Therefore is an adverbial connector and needs appropriate sentence boundaries. Use associated with rather than caused by when the evidence establishes only correlation.',wrong:'The sensor failed, therefore the trial stopped.',right:'The sensor failed; therefore, the trial stopped.',why:'A comma alone does not join these independent clauses in edited academic prose.',tasks:[{prompt:'Replace because of with because: The trial stopped because of a sensor failure. Begin The trial stopped because a sensor.',answers:['The trial stopped because a sensor failed.'],kind:'transformation',explanation:'Because needs a finite clause: a sensor failed.'},{prompt:'The result was unreliable ___ the sample was contaminated.',choices:['because','because of','due to'],answers:['because'],explanation:'Because can introduce the finite clause; because of and due to require a nominal complement.'}],production:'Link a supported cause to a consequence in two appropriately punctuated clauses.',model:'The sample was contaminated; therefore, the result was excluded.'},
 {id:'hedging-register',title:'Hedging, register and impersonal academic language',level:'C1',category:'Cohesion & academic English',concept:'Hedging calibrates a claim to the strength of the evidence. May, appears to, tends to and is likely to express different kinds of qualification. Impersonal frames can foreground the evidence rather than the researcher.',context:'A hedge should express genuine uncertainty, not decorate every sentence. Formality also involves precise verbs, appropriate collocations and explicit logical links. Avoid changing a cautious claim into a certainty during rewriting.',structure:'subject + may + base; appears/seems + to-infinitive; It is possible that + clause',examples:[['The intervention may reduce fatigue.','The effect is possible, not guaranteed.'],['It appears that the estimates are sensitive to the sampling method.','The claim is presented as a provisional inference.']],contrast:'May / must; formal / inflated',difference:'May allows a possibility; epistemic must is a strong inference. Formal prose should be precise, not needlessly abstract: use is often clearer than utilise unless the latter adds meaning.',wrong:'The evidence may proves the hypothesis.',right:'The evidence may support the hypothesis.',why:'A modal takes a base verb; support also avoids equating suggestive evidence with proof.',tasks:[{prompt:'Hedge with may without adding certainty: The intervention reduces fatigue.',answers:['The intervention may reduce fatigue.'],kind:'transformation',explanation:'May weakens the original assertion to a possibility and requires bare reduce.'},{prompt:'Select the appropriately cautious conclusion from limited observational data.',choices:['The association may reflect an unmeasured factor.','The association proves a universal cause.','The association is never uncertain.'],answers:['The association may reflect an unmeasured factor.'],kind:'context-selection',explanation:'May reflects uncertainty; neither universal proof nor absolute certainty follows from limited observational data.'}],production:'Write a cautious conclusion and identify what evidence would strengthen it.',model:'The change may reflect seasonal demand; a longer time series would help test this explanation.'},
 {id:'nominalisation',title:'Nominalisation and information structure',level:'C1',category:'Cohesion & academic English',concept:'Nominalisation turns a process into a noun phrase so it can become the topic of another clause. It can compact an argument and connect old information to a new evaluation, but can also hide agency and make prose dense.',context:'Move from given information toward new information when possible. Retain the actor if accountability matters. Avoid stacking several abstract nouns when a direct verb would be clearer.',structure:'The committee rejected X → The committee’s rejection of X; known topic → new comment',examples:[['The committee rejected the proposal. Its rejection delayed the project.','The noun rejection links the earlier event to a new consequence.'],['The rapid expansion of the city strained its transport system.','A process becomes the subject of the consequence clause.']],contrast:'Nominalisation / passive voice',difference:'Nominalisation changes a process into a noun phrase. Passive voice changes clause focus while keeping a verb. Both may conceal an actor, but they are different operations.',wrong:'The committee rejection the proposal delayed us.',right:'The committee’s rejection of the proposal delayed us.',why:'The nominal head rejection needs a possessive determiner for the actor and of for the affected proposal.',tasks:[{prompt:'Nominalise reject: The committee rejected the proposal, and this delayed the project. Begin The committee’s rejection.',answers:["The committee’s rejection of the proposal delayed the project."],kind:'transformation',explanation:'The noun phrase preserves both actor and object; delayed remains the main verb.'},{prompt:'Choose the nominalisation of expand.',choices:['expansion','expansive','expanding quickly'],answers:['expansion'],explanation:'Expansion is the noun; expansive is an adjective and expanding quickly is a nonfinite verb phrase.'}],production:'Link an event to a consequence using a nominalisation while preserving its actor.',model:'The council’s approval of the scheme enabled construction to begin.'},
 {id:'academic-context',title:'Academic argument, perspectives and formal communication',level:'C1',category:'Grammar in context',concept:'An argument distinguishes a claim, its evidence, a counterposition and a qualified response. Grammar encodes these relationships: concessive clauses acknowledge objections, reporting clauses attribute positions, and modal hedges restrict unsupported generalisations.',context:'For formal requests, indirect questions reduce abruptness without obscuring the action requested. When comparing perspectives, attribute each claim accurately rather than treating all reported views as facts.',structure:'Although + counterpoint, qualified claim; X argues that … whereas Y maintains that …; Could you clarify whether + statement order?',examples:[['Although the policy may reduce costs, its long-term effects remain uncertain.','The concession does not erase the limitation.'],['Could you clarify whether the revised figures include transport costs?','An indirect question makes a precise formal request.']],contrast:'Reporting a claim / endorsing a claim',difference:'The authors argue that attributes a view. The evidence establishes that is a stronger commitment by the current writer. Preserve that difference when paraphrasing.',wrong:'Could you clarify whether do the figures include tax?',right:'Could you clarify whether the figures include tax?',why:'The embedded whether-clause uses statement order, even inside a polite direct question.',tasks:[{prompt:'Make a formal indirect question: Do the figures include tax? Begin Could you clarify whether.',answers:['Could you clarify whether the figures include tax?'],kind:'transformation',explanation:'Whether introduces the yes/no issue, with statement order in the embedded clause.'},{prompt:'Which clearly attributes a view rather than endorsing it?',choices:['The authors argue that the policy is effective.','The policy is unquestionably effective.','The policy has certainly succeeded.'],answers:['The authors argue that the policy is effective.'],kind:'context-selection',explanation:'The reporting clause identifies the source; the other claims assert certainty directly.'}],production:'Write a short claim, acknowledge a competing perspective and qualify your conclusion.',model:'The authors argue that remote work improves access. Although this may be true, its effects depend on reliable infrastructure.'},
 {id:'trends-evaluation',title:'Describing trends, comparisons and cautious evaluation',level:'B2',category:'Grammar in context',concept:'Choose tense from the time window in the data. A finished period takes past forms; a period extending to now can take present perfect. Comparative clauses need equivalent quantities, and modifiers distinguish the size of a change from its speed.',context:'Use rose by for the amount of change and rose to for the endpoint. An observed trend is not automatically a forecast or a causal explanation. State the unit and baseline to avoid misleading comparisons.',structure:'rose by + difference / rose to + endpoint; has increased since + start; twice as + adjective + as',examples:[['Costs rose from 50 to 60 units, an increase of 10 units.','The endpoints and change are explicitly distinguished.'],['Output has increased steadily since January.','The observation period extends to the present.']],contrast:'Rose by / rose to; higher than / as high as',difference:'By measures a difference; to gives an endpoint. Twice as high as compares a ratio; twice higher than is often ambiguous and is best avoided in technical prose.',wrong:'Costs rose by 60 units, from 50 to 60.',right:'Costs rose by 10 units, from 50 to 60.',why:'The difference is 10, while 60 is the endpoint. Grammar must preserve the numerical claim.',tasks:[{prompt:'Costs moved from 50 to 60 units. Complete with the preposition and amount: Costs rose ___ units.',answers:['by 10'],explanation:'By introduces the change: 60 minus 50 equals 10.'},{prompt:'Rewrite using twice as high as: A is 20 units and B is 10 units. Begin A is.',answers:['A is twice as high as B.'],kind:'transformation',explanation:'The ratio is two to one; twice as high as preserves it without the ambiguity of twice higher.'}],production:'Describe one completed change and distinguish the endpoint from its magnitude.',model:'Revenue rose by 12 units to 72 units in 2024.'},
 {id:'subjunctive-precision',title:'Subjunctive, concessive inversion and advanced modal scope',level:'C2',category:'Precision & register',concept:'The mandative subjunctive uses a base verb after demands and recommendations, especially in formal American English. Formal British English also commonly uses should. Concessive inversion such as difficult though it may be foregrounds an acknowledged obstacle.',context:'C2 here is an extension pathway for precision and register, not proof that a structure belongs exclusively to C2. Scope matters: need not have done implies an action was performed unnecessarily; did not need to do does not by itself establish whether it happened.',structure:'recommend that + subject + base; adjective + though + subject + may be; need not have + participle',examples:[['The panel recommended that the report be revised.','Be is a mandative base form, not agreement with report.'],['Difficult though it may be, the evidence must be examined.','Fronted difficult creates formal concession.'],['You need not have printed it; a digital copy was sufficient.','Printing occurred, but was unnecessary.']],contrast:'Need not have done / did not need to do',difference:'Need not have done presents a performed but unnecessary action. Did not need to do states absence of necessity and needs context to determine whether the action happened.',wrong:'The panel insisted that he submits it immediately. (mandative meaning)',right:'The panel insisted that he submit it immediately.',why:'The specified mandative reading selects base submit; should submit is another accepted option. Insisted that he submitted can instead assert a past fact.',tasks:[{prompt:'Use the mandative subjunctive: The panel recommended that the report ___ revised.',answers:['be'],explanation:'Mandative be is invariant; is would not form the requested subjunctive.'},{prompt:'Rewrite with concessive inversion: Although it may be difficult, the task is necessary. Begin Difficult though.',answers:['Difficult though it may be, the task is necessary.'],kind:'transformation',explanation:'The concession is preserved; this is not ordinary question inversion.'},{prompt:'Which explicitly implies unnecessary printing actually happened?',choices:['You need not have printed it.','You did not need to print it.','You must not print it.'],answers:['You need not have printed it.'],explanation:'Need not have printed expresses unnecessary completed action. Did not need to does not alone settle occurrence; must not prohibits.'}],production:'Make a formal recommendation and explain a nuanced distinction in modal meaning.',model:'I recommend that the evidence be reviewed. The team need not have repeated the trial; the earlier results were sufficient.'}
];

export const advancedLessons:GrammarLesson[]=units.map(u=>({id:u.id,title:u.title,level:u.level,category:u.category,group:u.level==='A1'||u.level==='A2'?'Foundations':u.level==='B1'?'Intermediate':u.level==='B2'?'Upper Intermediate':'Advanced',introduction:[u.concept,u.context],purpose:u.context,structures:[u.structure],examples:u.examples.map(([sentence,why])=>({sentence,why})),mistakes:[{incorrect:u.wrong,correct:u.right,why:u.why}],comparisons:[{contrast:u.contrast,explanation:u.difference}],summary:[u.concept,u.difference],production:{prompt:u.production,reference:u.model,criteria:['Use the target structure accurately.','Preserve the stated time, voice and logical relationship.','Check the intended meaning and appropriateness for the context.']},references}));
export const advancedExercises:GrammarExercise[]=units.flatMap(u=>u.tasks.map((q,i)=>({...q,id:`${u.id}-v1-${i+1}`,lessonId:u.id,kind:q.kind||(q.choices?'multiple-choice':'fill-blank')})));
export const legacyLevels:Record<string,CEFRLevel>={articles:'A1',agreement:'A1',present:'A2',past:'A2',perfect:'B1',future:'B1',modals:'B1',passive:'B1',relatives:'B2','verb-patterns':'B1',conditionals:'B2',reported:'B2',inversion:'C1'};
export const legacyCategories:Record<string,string>={articles:'Foundations',agreement:'Foundations',present:'Tenses & aspect',past:'Tenses & aspect',perfect:'Tenses & aspect',future:'Tenses & aspect',modals:'Modals & deduction',passive:'Verb patterns',relatives:'Sentence structures','verb-patterns':'Verb patterns',conditionals:'Conditionals',reported:'Verb patterns',inversion:'Sentence structures'};
